<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Authentication\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Features\OAuth\Profile\Domain\OidcProfile;
use Civi\Lughauth\Features\OAuth\Profile\Domain\Gateway\ProfileGateway;
use OpenApi\Attributes as OA;

class UserInfoController
{
    public function __construct(
        private readonly Context $context,
        private readonly ProfileGateway $profileGateway,
    ) {
    }

    #[OA\Get(
        path: '/oauth/openid/{tenant}/userinfo',
        summary: 'OIDC UserInfo Endpoint',
        description: 'Returns claims about the authenticated user. Requires Bearer access token with openid scope.',
        tags: ['OIDC'],
        security: [['bearerAuth' => []]],
        parameters: [
            new OA\Parameter(name: 'tenant', in: 'path', required: true, schema: new OA\Schema(type: 'string')),
        ],
        responses: [
            new OA\Response(
                response: 200,
                description: 'User claims',
                content: new OA\JsonContent(properties: [
                    new OA\Property(property: 'sub', type: 'string'),
                    new OA\Property(property: 'name', type: 'string'),
                    new OA\Property(property: 'email', type: 'string'),
                    new OA\Property(property: 'given_name', type: 'string'),
                    new OA\Property(property: 'family_name', type: 'string'),
                    new OA\Property(property: 'picture', type: 'string'),
                    new OA\Property(property: 'locale', type: 'string'),
                    new OA\Property(property: 'zoneinfo', type: 'string'),
                    new OA\Property(property: 'phone_number', type: 'string'),
                    new OA\Property(property: 'updated_at', type: 'integer'),
                ])
            ),
            new OA\Response(response: 401, description: 'Unauthorized'),
        ]
    )]
    public function get(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $identity = $this->context->getIdentity();
        $claims = ['sub' => $identity->id];

        $scopes = $this->parseScopes($identity->scope);

        if (in_array('email', $scopes, true)) {
            $claims['email'] = $identity->email;
        }

        if (in_array('profile', $scopes, true) || in_array('phone', $scopes, true)) {
            $profile = $identity->id !== null
                ? $this->profileGateway->findByUser($identity->id)
                : null;

            if ($profile !== null) {
                $oidcClaims = $this->toOidcClaims($profile);

                if (in_array('profile', $scopes, true)) {
                    foreach (['name', 'given_name', 'family_name', 'middle_name', 'nickname', 'preferred_username', 'picture', 'website', 'gender', 'birthdate', 'zoneinfo', 'locale', 'updated_at'] as $key) {
                        if (array_key_exists($key, $oidcClaims)) {
                            $claims[$key] = $oidcClaims[$key];
                        }
                    }
                }

                if (in_array('phone', $scopes, true)) {
                    foreach (['phone_number', 'phone_number_verified'] as $key) {
                        if (array_key_exists($key, $oidcClaims)) {
                            $claims[$key] = $oidcClaims[$key];
                        }
                    }
                }
            }
        }

        $encoded = json_encode($claims);
        $response->getBody()->write($encoded !== false ? $encoded : '{}');
        return $response->withHeader('Content-Type', 'application/json');
    }

    private function parseScopes(?string $scope): array
    {
        if ($scope === null || $scope === '') {
            return [];
        }
        return explode(' ', $scope);
    }

    private function toOidcClaims(OidcProfile $profile): array
    {
        $claims = [];

        $nameParts = array_filter([$profile->givenName, $profile->familyName]);
        if ($nameParts !== []) {
            $claims['name'] = implode(' ', $nameParts);
        }

        $mapping = [
            'given_name'            => $profile->givenName,
            'family_name'           => $profile->familyName,
            'middle_name'           => $profile->middleName,
            'nickname'              => $profile->nickname,
            'preferred_username'    => $profile->preferredUsername,
            'picture'               => $profile->pictureUrl,
            'website'               => $profile->websiteUrl,
            'gender'                => $profile->gender,
            'birthdate'             => $profile->birthdate,
            'zoneinfo'              => $profile->zoneinfo,
            'locale'                => $profile->locale,
            'phone_number'          => $profile->phoneNumber,
        ];

        foreach ($mapping as $key => $value) {
            if ($value !== null) {
                $claims[$key] = $value;
            }
        }

        if ($profile->phoneNumberVerified !== null) {
            $claims['phone_number_verified'] = $profile->phoneNumberVerified;
        }

        if ($profile->addressJson !== null) {
            $decoded = json_decode($profile->addressJson, true);
            if (is_array($decoded)) {
                $claims['address'] = $decoded;
            }
        }

        if ($profile->updatedAt !== null) {
            $ts = strtotime($profile->updatedAt);
            if ($ts !== false) {
                $claims['updated_at'] = $ts;
            }
        }

        return $claims;
    }
}
